/bin/bash -lc "python - <<'PY'
from sim import Sim
import mujoco
sim=Sim()
for i in range(sim.model.nbody):
    name=mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_BODY, i)
    if name:
        print('body', i, name)
print('sites:')
for i in range(sim.model.nsite):
    name=mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_SITE, i)
    if name:
        print('site', i, name)
print('geoms:')
for i in range(sim.model.ngeom):
    name=mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_GEOM, i)
    if name and ('finger' in name or 'hand' in name or 'panda' in name or 'ee' in name):
        print('geom', i, name)
PY"

